187 @Composable
188 private fun CarouselBrowser(
189     database: LibraryDatabase, artwork: EmbeddedArtwork, albums: LibraryGroupPage, revision: Int,
190     active: Boolean, initialAlbum: Int, onSettled: (Int) -> Unit, bottomInset: Dp,
191     onSelect: (LibraryContextRequest, (Boolean) -> Unit) -> Unit,
192     onAdd: (String, (Boolean) -> Unit) -> Unit, onPlayNext: (String, (Boolean) -> Unit) -> Unit,
193     onPlaylistSong: (String) -> Unit,
194 ) {
195     val count = albums.total
196     val pager = rememberPagerState(initialPage = carouselStartPage(initialAlbum.coerceIn(0, count - 1), count)) {
197         if (count == 1) 1 else Int.MAX_VALUE
198     }
199     val scope = rememberCoroutineScope()
200     val reducedMotion = scope.coroutineContext[MotionDurationScale]?.scaleFactor == 0f
201     val flingBehavior = PagerDefaults.flingBehavior(
202         state = pager, pagerSnapDistance = PagerSnapDistance.atMost(if (reducedMotion) 1 else CAROUSEL_FLING_PAGES),
203     )
204     val pages = remember(albums) { mutableStateMapOf(0 to albums.groups) }
205     val backdrops = remember(revision) { CarouselBackdrops() }
206     val covers = remember(revision) { mutableStateMapOf<AlbumIdentity, CarouselCover>() }
207     var metadataRetry by remember { mutableIntStateOf(0) }
208     var metadataFailed by remember { mutableStateOf(false) }
209     var rolling by remember { mutableStateOf(false) }
210     var selection by remember { mutableStateOf<CarouselSelection?>(null) }
211     var failedAlbum by remember { mutableStateOf<AlbumIdentity?>(null) }
212     var selectionRetry by remember { mutableIntStateOf(0) }
213     var trackInfo by remember { mutableStateOf<LibrarySong?>(null) }
214     var playbackFailed by remember { mutableStateOf(false) }
215     var albumHeaderProgress by rememberSaveable { mutableFloatStateOf(0f) }
216     val headerTravel = with(LocalDensity.current) { 136.dp.toPx() }
217 
218     fun batchFor(index: Int) = index / CAROUSEL_ALBUM_BATCH * CAROUSEL_ALBUM_BATCH
219     fun nearbyBatches(index: Int) = (-CAROUSEL_FLING_PAGES..CAROUSEL_FLING_PAGES).mapTo(mutableSetOf()) {
220         batchFor(carouselAlbumIndex(index + it, count))
221     }
222     fun albumAt(index: Int) = pages[batchFor(index)]?.getOrNull(index % CAROUSEL_ALBUM_BATCH)
223     suspend fun loadBatches(batches: Set<Int>) {
224         for (batch in batches) {
225             if (batch !in pages) pages[batch] = withContext(Dispatchers.IO) {
226                 database.groups(LibraryGroupKind.ALBUM, limit = CAROUSEL_ALBUM_BATCH, offset = batch).groups
227             }
228         }
229     }
230 
231     val settledIndex = carouselAlbumIndex(pager.settledPage, count)
232     val centered = albumAt(settledIndex)
233     val centeredAlbum = centered?.identity()
234     val trackList = key(centeredAlbum) { rememberLazyListState() }
235     suspend fun animateHeaderTo(target: Float) {
236         if (target > 0f && (rolling || pager.isScrollInProgress || selection?.album != centeredAlbum)) return
237         if (target != albumHeaderProgress) animate(albumHeaderProgress, target, animationSpec = EvannaMotion.exit) { value, _ ->
238             albumHeaderProgress = value
239         }
240     }
241     fun moveHeader(delta: Float): Offset {
242         if (rolling || pager.isScrollInProgress) return Offset.Zero
243         if (delta < 0f && selection?.album != centeredAlbum) return Offset.Zero
244         if (delta > 0f && trackList.canScrollBackward) return Offset.Zero
245         val before = albumHeaderProgress
246         albumHeaderProgress = (before - delta / headerTravel).coerceIn(0f, 1f)
247         return Offset(0f, (before - albumHeaderProgress) * headerTravel)
248     }
249     suspend fun settleHeader(velocity: Float) {
250         val progress = albumHeaderProgress
251         if (progress == 0f || trackList.canScrollBackward) return
252         val target = when {
253             velocity > 0f -> 0f
254             velocity < 0f || progress >= 0.5f -> 1f
255             else -> 0f
256         }
257         animateHeaderTo(target)
258     }
259     val headerDrag = rememberDraggableState { moveHeader(it) }
260     val headerScroll = remember(headerTravel, trackList, pager) {
261         object : NestedScrollConnection {
262             override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset =
263                 if (source == NestedScrollSource.UserInput && available.y < 0f) moveHeader(available.y) else Offset.Zero
264 
265             override fun onPostScroll(consumed: Offset, available: Offset, source: NestedScrollSource): Offset =
266                 if (source == NestedScrollSource.UserInput && available.y > 0f) moveHeader(available.y) else Offset.Zero
267 
268             override suspend fun onPreFling(available: Velocity): Velocity {
269                 if (albumHeaderProgress in 0f..<1f && available.y < 0f) settleHeader(available.y)
270                 return Velocity.Zero
271             }
272 
273             override suspend fun onPostFling(consumed: Velocity, available: Velocity): Velocity {
274                 settleHeader(available.y)
275                 return Velocity.Zero
276             }
277         }
278     }
279     LaunchedEffect(trackList) {
280         var scrolledPastTop = false
281         snapshotFlow { trackList.canScrollBackward to trackList.isScrollInProgress }.collectLatest { (scrolled, moving) ->
282             if (scrolled) scrolledPastTop = true
283             else if (!moving && scrolledPastTop) {
284                 animateHeaderTo(0f)
285                 scrolledPastTop = false
286             }
287         }
288     }
289     LaunchedEffect(active, metadataRetry) {
290         if (!active) return@LaunchedEffect
291         snapshotFlow {
292             nearbyBatches(carouselAlbumIndex(pager.currentPage, count)) + batchFor(carouselAlbumIndex(pager.settledPage, count))
293         }.collectLatest { wanted ->
294             metadataFailed = readCarousel { loadBatches(wanted) }.isFailure
295             if (!rolling) (pages.keys - wanted).forEach { pages.remove(it) }
296         }
297     }
298     LaunchedEffect(active, settledIndex) {
299         if (active) onSettled(settledIndex)
300     }
301     LaunchedEffect(active, centeredAlbum, selectionRetry) {
302         val album = centeredAlbum ?: return@LaunchedEffect
303         if (!active || selection?.album == album) return@LaunchedEffect
304         failedAlbum = null
305         readCarousel {
306             withContext(Dispatchers.IO) {
307                 val filter = LibraryFilter(kind = LibraryGroupKind.ALBUM, value = album.title, albumArtist = album.albumArtist)
308                 CarouselSelection(album, database.page(filter = filter), database.albumSummary(album))
309             }
310         }.onSuccess { selection = it }.onFailure { failedAlbum = album }
311     }
312 
313     LaunchedEffect(active, revision) {
314         if (!active) return@LaunchedEffect
315         snapshotFlow {
316             val page = pager.currentPage
317             listOf(page, pager.settledPage, page - 1, page + 1)
318                 .filter { it in 0 until pager.pageCount }
319                 .mapNotNull { albumAt(carouselAlbumIndex(it, count))?.identity() }.distinct()
320         }.collectLatest { wanted ->
321             (covers.keys - wanted.toSet()).forEach(covers::remove)
322             for (album in wanted) {
323                 if (album !in covers) {
324                     covers[album] = CarouselCover(readCarousel { artwork.album(album, ArtworkSize.MEDIUM) }.getOrNull())
325                 }
326                 covers[album]?.bitmap?.let { backdrops.prepare(album, it) }
327             }
328         }
329     }
330 
331     fun playFocusedAlbum(page: Int): Boolean {
332         if (!active || rolling || albumHeaderProgress > 0f || pager.isScrollInProgress ||
333             page != pager.settledPage || LocalLibrary.scanning || LocalLibrary.managingFolders) return false
334         val album = albumAt(carouselAlbumIndex(page, count))?.identity() ?: return false
335         val filter = LibraryFilter(kind = LibraryGroupKind.ALBUM, value = album.title, albumArtist = album.albumArtist)
336         onSelect(LibraryContextRequest(filter, null, LibraryContextAction.PLAY_FIRST)) { success ->
337             if (!success) playbackFailed = true
338         }
339         return true
340     }
341 
342     fun moveTo(page: Int) {
343         if (!active || rolling || page !in 0 until pager.pageCount || page == pager.currentPage) return
344         scope.launch {
345             if (reducedMotion) pager.scrollToPage(page)
346             else pager.animateScrollToPage(page, animationSpec = EvannaMotion.enter)
347         }
348     }
349     fun roll() {
350         val target = randomCarouselAlbum(settledIndex, count) ?: return
351         if (!active || rolling || pager.isScrollInProgress || albumHeaderProgress > 0f) return
352         rolling = true
353         scope.launch {
354             try {
355                 val ready = readCarousel { loadBatches(nearbyBatches(target)) }.isSuccess
356                 if (!ready) {
357                     metadataFailed = true
358                     return@launch
359                 }
360                 val page = carouselPageForAlbum(pager.currentPage, target, count)
361                 if (reducedMotion) pager.scrollToPage(page)
362                 else pager.animateScrollToPage(page, animationSpec = tween(620))
363             } finally {
364                 rolling = false
365                 val keep = nearbyBatches(carouselAlbumIndex(pager.currentPage, count)) +
366                     batchFor(carouselAlbumIndex(pager.settledPage, count))
367                 (pages.keys - keep).forEach { pages.remove(it) }
368             }
369         }
370     }
371 
372     val look = LocalLookStyle.current.look
373     val centeredCover = centeredAlbum?.let(covers::get)
374     var accent by remember(revision) { mutableStateOf<Color?>(null) }
375     var themedAlbum by remember(revision) { mutableStateOf<AlbumIdentity?>(null) }
