private const val IDLE_STATUS = "Saved on this device. Tap a song to queue this list and play from there."
private const val READY_STATUS = "Scan complete. Saved songs are ready to browse."

internal object LocalLibrary {
    @Volatile private var database: LibraryDatabase? = null
    @Synchronized fun database(context: Context): LibraryDatabase = database
        ?: LibraryDatabase(context.applicationContext).also { database = it }
    private var artwork: EmbeddedArtwork? = null
    @Synchronized fun artwork(context: Context): EmbeddedArtwork = artwork
        ?: EmbeddedArtwork(context.applicationContext, database(context)).also { artwork = it }
    private var lyrics: EmbeddedLyrics? = null
    @Synchronized fun lyrics(context: Context): EmbeddedLyrics = lyrics
        ?: EmbeddedLyrics(database(context)).also { lyrics = it }

    // Folder scans belong to the app, not to the Library screen, so switching tabs never stops one.
    private val scans = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    private val scanQueue = LibraryScanQueue()
    private var scanJob: Job? = null
    private var startupSyncStarted = false
    private var startupSyncing by mutableStateOf(false)
    var scanning by mutableStateOf(false)
        private set
    var activeScanRoot by mutableStateOf<String?>(null)
        private set
    val indexing get() = scanning || startupSyncing
    var managingFolders by mutableStateOf(false)
        private set
    /** The Library screen's status line: scan progress and results, or the last queue add. */
    var status by mutableStateOf(IDLE_STATUS)
    /** True while the status only says all is well, so the list can leave that line out. */
    val statusIsIdle get() = status == IDLE_STATUS || status == READY_STATUS
    /** Counts finished scans; lists and covers reload when it changes. */
    var scansFinished by mutableIntStateOf(0)
        private set

    /** Runs once per process launch without changing foreground scan controls or status. */
    fun syncOnLaunch(context: Context) {
        if (startupSyncStarted) return
        startupSyncStarted = true
        val app = context.applicationContext
        scanQueue.startup(scans) {
            startupSyncing = true
            var changed = false
            try {
                withContext(Dispatchers.IO) {
                    val store = database(app)
                    releaseRemovedGrants(app, store)
                    val roots = store.rootUris().filter { isLocalTree(app, Uri.parse(it)) }
                    scanLibraryBatch(roots, store, { source(app, store, it) }, silent = true, onChanged = { changed = true })
                }
            } catch (cancelled: CancellationException) {
                throw cancelled
            } catch (failure: Exception) {
                android.util.Log.w("LocalLibrary", "Startup library sync did not finish", failure)
            } finally {
                if (changed) scansFinished++
                startupSyncing = false
            }
        }
    }

    private fun source(app: Context, store: LibraryDatabase, root: String) =
        SafLibrarySource(app, Uri.parse(root), store.excludedFolders(root).map { it.id }.toSet())

    /** Main thread only. Adds or reconnects the folder before scanning it when [add] is true. */
    fun scan(context: Context, uri: Uri? = null, add: Boolean = false) {
        if (scanning || managingFolders) return
        val app = context.applicationContext
        scanning = true
        status = if (uri == null) "Scanning music folders…" else "Scanning folder…"
        scanJob = scans.launch {
            try {
                val ready = scanQueue.userAction {
                    withContext(Dispatchers.IO) {
                        val store = database(app)
                        releaseRemovedGrants(app, store)
                        val selected = when {
                            add -> listOf(add(app, requireNotNull(uri), store).toString())
                            uri != null -> listOf(uri.toString())
                            else -> store.rootUris()
                        }
                        var nextUpdate = 0L
                        scanLibraryBatch(selected, store, { source(app, store, it) }, onRoot = { root ->
                            withContext(Dispatchers.Main) { activeScanRoot = root }
                        }) { count ->
                            val now = SystemClock.elapsedRealtime()
                            if (now >= nextUpdate) {
                                nextUpdate = now + 250
                                withContext(Dispatchers.Main) { status = "Scanning… $count audio files checked." }
                            }
                        }
                        val readyRoots = store.roots().filter { it.state == LibraryRootState.READY }.map { it.uri }.toSet()
                        selected.all { it in readyRoots }
                    }
                }
                status = if (ready) READY_STATUS
                    else "Scan incomplete. Saved songs were kept. Reconnect the folder and rescan."
            } catch (cancelled: CancellationException) {
                status = "Scan cancelled. Saved songs were kept."
                throw cancelled
            } catch (overlap: FolderOverlap) {
                status = overlap.message.orEmpty()
            } catch (_: Exception) {
                status = "The folder could not be indexed. Use a local phone or SD-card folder, or select it again to renew access. Saved songs were kept."
            } finally { activeScanRoot = null; scanning = false; scansFinished++ }
        }
    }

    fun cancelScan() { if (!managingFolders) scanJob?.cancel() }

    fun cleanupRemovedFolders(context:Context) = folderAction(context,catalogChange=false) {app,store ->
        val pending=store.pendingGrantReleases().size
        if(pending==0)null else if(releaseRemovedGrants(app,store))"Removed folder access released."
        else "A removed folder's access could not be released yet. Evanna will retry on the next scan or launch."
    }
    fun removeFolder(context:Context,root:LibraryRoot) = folderAction(context,"Removing music folder…") {app,store ->
        store.removeRoot(root.uri)
        if(releaseRemovedGrants(app,store))"Folder removed from Evanna. Music files and personal lists were kept."
        else "Folder removed; music files kept. Evanna will retry releasing access on the next scan or launch."
    }
    fun includeFolder(context:Context,root:String,id:String) = folderAction(context,"Including subfolder…") {_,store ->
        store.includeFolder(root,id);"Folder included again. Rescan its music folder to restore the songs."
    }
    fun excludeFolder(context:Context,root:String,directory:LibraryDocument) = folderAction(context,"Checking subfolder contents…") {app,store ->
        require(directory.mime==DIRECTORY_MIME && directory.id.length<=8192)
        val tree=Uri.parse(root);val source=SafLibrarySource(app,tree)
        val top=source.root()
        require(directory.id!=top.id)

# Evanna updates and player experience implementation plan

**Goal.** Notify users about installable Evanna releases, add the public GitHub footer, improve Carousel and album browsing, and refine the mini-player, Now Playing, and landscape display.

**Architecture.** Use the public GitHub Releases endpoint and existing Compose UI and preferences. Reuse the album playback request, artwork loader, and player motion already in the app.

**Scope.** This plan follows the November 12 requests and their screenshots. Proposed defaults are an automatic GitHub check for release builds, browser-assisted installation, and a stationary fade for programmatic Now Playing transitions. Keep the existing drag interaction. The automatic check requires changing the current Internet permission and corresponding README claim.

**Starting point.** The checkout has in-progress edits to `NowPlaying.kt`, `PlayerBackdrop.kt`, `PlayerScreens.kt`, `library/CarouselScreen.kt`, and `ui/Actions.kt`. Inspect and preserve them. Capture the baseline from the actual build being compared.

## 1. GitHub Settings footer

- [ ] In `MainActivity.kt`, append a centered, subdued text link labeled **Evanna on GitHub** as the final item of the top-level Settings `LazyColumn` (`PlayerScreen.OUTPUT`). Use the existing bottom inset. Give the link a full touch target and accessible link semantics. The footer sits below the settings groups and remains separate from search results, with plain text styling and no panel, icon, or chevron.
- [ ] Use `https://github.com/dripdropfromablock/evanna-public` as the shared repository constant. Open it using the external URL intent pattern in MainActivity. Handle a missing browser using existing feedback.
- [ ] Verify the footer scrolls above the dock, appears only on main Settings, stays legible in both appearances, and opens the public URL.

## 2. App updates with snooze

- [ ] Establish a release contract. Use GitHub's latest published stable release for `dripdropfromablock/evanna-public`. Publish a small `evanna-update.json` release asset with `versionName` and an `apks` object keyed by Android ABI. Each entry has `assetName` and numeric `versionCode`, taken from the final signed APK. Require the named APK to be present on the same release. Select the first compatible ABI in `Build.SUPPORTED_ABIS`. Validate against the final APK before publishing and confirm the existing release signing key can update a prior installed release in place. The repository currently declares version code 1 and supports optional ABI-specific APKs. Public release contents remain to be verified.
- [ ] Add `app/src/main/java/com/evanna/player/AppUpdates.kt` with `AppUpdate(versionCode: Long, versionName: String, downloadUrl: String)` and a suspend check returning `AppUpdate?`. Use the existing coroutines and Android JSON/platform HTTPS APIs. Accept only the expected release and download host/path, bound response sizes and timeouts, and compare the candidate APK's version code to the installed package's `longVersionCode`. Treat offline, rate limits, malformed or absent metadata, missing assets, and unsupported ABIs as silent misses. Cancel with the foreground lifecycle. Exclude debuggable builds so development installs do not get public release prompts.
- [ ] In `AndroidManifest.xml`, replace the explicit Internet removal with the normal Internet permission for the update request. Update the README to say playback and library work offline and automatic update checks contact GitHub. Send no app account, device ID, or music-library data.
- [ ] In `MainActivity.kt`, run one background check after startup work has been scheduled, and recheck on foreground only when due. Persist the last successful check and its validated candidate (or empty result) for a 24-hour refresh interval. Revalidate the cached candidate against the installed version before prompting, so a restart during snooze can still show it when the timer expires. Keep a single in-flight check and short-lived in-process failure backoff to avoid repeated requests on rotation or quick resumes. Persist the snoozed release code and expiry in the existing UI preferences. At expiry, re-evaluate on foreground and while the app stays foregrounded. A newer release can prompt when discovered during regular checks.
- [ ] Use the existing dialog components. Show **Update available**, the version, **Update now**, and **Update later**. Update later opens **1 hour**, **1 day**, and **1 week** choices (1, 24, and 168 hours from selection). Back or outside dismissal snoozes that release for 1 hour. Update now opens the verified APK download link in the browser and suppresses a repeat prompt for 1 hour after a successful handoff. Android handles installation and user confirmation. Keep one dialog across recomposition and defer it while another modal is open.
- [ ] Add `app/src/test/java/com/evanna/player/AppUpdatesTest.kt` for newer/equal/older numeric versions, ABI priority, missing/malformed metadata, wrong release URL, and the exact before/at-expiry behavior for all three durations plus a newer release during an old snooze. Verify on device with an older signed build and a test release fixture. Cover restart during snooze, offline startup, a cancelled install, and successful update with library and settings retained.

## 3. Double-tap the focused album to play

- [ ] In `library/CarouselScreen.kt`, add a double-tap action to the settled card using Compose's combined click handling. Keep single-tap navigation on neighboring cards. Execute playback only when the tapped page is still settled, the pager is idle, Carousel is active, the full card is visible, and the library can accept playback. Expose an accessible **Play album from first track** action on the focused card.
- [ ] Reuse `onSelect` with `LibraryContextRequest(LibraryFilter(kind = LibraryGroupKind.ALBUM, value = album.title, albumArtist = album.albumArtist), null, LibraryContextAction.PLAY_FIRST)`. This follows the existing album play path, so track order and queue construction use the full album. Route failure through the existing Carousel feedback. Prevent one gesture from firing twice.
